package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class StatChecks {
 @Test public void speciesOnlyStatsHaveNoIvOrEvBonus(){PokemonStats.Values s=PokemonStats.at(PokemonStats.Species.CHARMANDER,20);assertEquals(45,s.hp);assertEquals(25,s.attack);assertEquals(22,s.defense);assertEquals(29,s.specialAttack);assertEquals(25,s.specialDefense);assertEquals(31,s.speed);}
 @Test public void allSixStatsGrowAndEvolutionUsesDifferentBases(){PokemonStats.Values a=PokemonStats.at(PokemonStats.Species.CHARMANDER,20),b=PokemonStats.at(PokemonStats.Species.CHARMANDER,40),c=PokemonStats.at(PokemonStats.Species.CHARIZARD,40);assertTrue(b.hp>a.hp&&b.attack>a.attack&&b.defense>a.defense&&b.specialAttack>a.specialAttack&&b.specialDefense>a.specialDefense&&b.speed>a.speed);assertTrue(c.hp>b.hp&&c.attack>b.attack&&c.defense>b.defense&&c.specialAttack>b.specialAttack&&c.specialDefense>b.specialDefense&&c.speed>b.speed);}
 @Test public void statsClampLevels(){assertEquals(PokemonStats.at(PokemonStats.Species.CHARMANDER,1).hp,PokemonStats.at(PokemonStats.Species.CHARMANDER,-1).hp);assertEquals(PokemonStats.at(PokemonStats.Species.CHARMANDER,100).attack,PokemonStats.at(PokemonStats.Species.CHARMANDER,200).attack);}
 @Test public void physicalAndSpecialDefenseAreSeparateInActualHits(){GameWorld w=new GameWorld();w.enemies.clear();w.level=30;GameWorld.Enemy e=new GameWorld.Enemy(195,112,true);e.level=30;e.hp=e.maxHp=5000;e.timer=1000;w.enemies.add(e);int physical=w.damageAgainst(GameWorld.Skill.DRAGON_CLAW,e),special=w.damageAgainst(GameWorld.Skill.FIRE_PLEDGE,e);e.defenseStage=2;assertTrue(w.damageAgainst(GameWorld.Skill.DRAGON_CLAW,e)<physical);assertEquals(special,w.damageAgainst(GameWorld.Skill.FIRE_PLEDGE,e));e.defenseStage=0;e.specialDefenseStage=2;assertEquals(physical,w.damageAgainst(GameWorld.Skill.DRAGON_CLAW,e));assertTrue(w.damageAgainst(GameWorld.Skill.FIRE_PLEDGE,e)<special);TestWorlds.equip(w,GameWorld.Skill.FIRE_PLEDGE);w.setDropSeed(0);w.trySkill(0);for(int n=0;n<35;n++)w.step(1f/60,0,false,false);assertEquals(w.damageAgainst(GameWorld.Skill.FIRE_PLEDGE,e),5000-e.hp);}
 @Test public void playerLevelChangesOffenseAndSpeedButNotIncomingHeartDamage(){GameWorld w=new GameWorld();GameWorld.Enemy e=new GameWorld.Enemy(200,112,true);e.level=30;int incoming=w.enemyDamage(e,true,100);float speed=w.movementSpeed();w.level=50;assertEquals(incoming,w.enemyDamage(e,true,100));assertTrue(w.movementSpeed()>speed);}
 @Test public void enemyLevelsMatchPlayerAcrossZonesAndBossHasDurability(){GameWorld w=new GameWorld();int lv=w.enemies.get(0).level,hp=w.enemies.get(0).maxHp;w.stageComplete=true;assertTrue(w.advanceStage());assertEquals(w.level,w.enemies.get(0).level);assertEquals(hp,w.enemies.get(0).maxHp);while(w.mapIndex<5){w.stageComplete=true;w.advanceStage();}assertEquals(PokemonStats.Species.RATICATE,w.boss.species);assertTrue(w.boss.maxHp>w.boss.stats().hp*2);}
 @Test public void skillSilhouettesAreDistinctAndEffectsFreezeThenClear(){assertNotEquals(SkillVisual.style(GameWorld.Skill.FIRE_BLAST),SkillVisual.style(GameWorld.Skill.FLAMETHROWER));assertNotEquals(SkillVisual.style(GameWorld.Skill.FANG),SkillVisual.style(GameWorld.Skill.FIRE_PUNCH));assertNotEquals(SkillVisual.style(GameWorld.Skill.HEAT_WAVE),SkillVisual.style(GameWorld.Skill.FIRE_SPIN));GameWorld w=new GameWorld();w.enemies.clear();TestWorlds.equip(w,GameWorld.Skill.SCRATCH);w.trySkill(0);for(int i=0;i<15;i++)w.step(1f/60,0,false,false);assertFalse(w.skillVisuals.isEmpty());float age=w.skillVisuals.get(0).age;w.paused=true;w.step(1f/30,0,false,false);assertEquals(age,w.skillVisuals.get(0).age,0);w.restart();assertTrue(w.skillVisuals.isEmpty());}
}
